PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?filmTitle ?director ?directorName ?birthDate WHERE {
  VALUES ?film { dbr:Carlo_Giuliani,_Boy dbr:Ned_Rifle }

  OPTIONAL { ?film dbp:name ?filmTitle . }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }
  FILTER(BOUND(?director))

  OPTIONAL { ?director dbp:name ?directorName . }

  # birth date (prefer dbp:birthDate)
  OPTIONAL { ?director dbp:birthDate ?bdate1 . }
  OPTIONAL { ?director dbo:birthDate ?bdate2 . }
  BIND( COALESCE(?bdate1, ?bdate2) AS ?birthDate )
}
LIMIT 100

