PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmTitle ?director ?directorName ?birthDate
WHERE {
  VALUES ?film { 
    <http://dbpedia.org/resource/Carlo_Giuliani,_Boy> 
    <http://dbpedia.org/resource/Ned_Rifle> 
  }

  # film title (prefer dbp:name, fallback to dbp:title)
  OPTIONAL { ?film dbp:name ?filmTitle . }
  OPTIONAL { ?film dbp:title ?filmTitle . }

  # director (prefer dbp:director, fallback to dbo:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }
  FILTER(BOUND(?director))

  # director name (prefer dbp:name, fallback to rdfs:label@en)
  OPTIONAL { ?director dbp:name ?directorName . }
  OPTIONAL { 
    ?director rdfs:label ?directorName .
    FILTER (lang(?directorName) = "en")
  }

  # director birth date (prefer dbp:birthDate, fallback to dbo:birthDate)
  OPTIONAL { ?director dbp:birthDate ?bdate1 . }
  OPTIONAL { ?director dbo:birthDate ?bdate2 . }
  BIND( COALESCE(?bdate1, ?bdate2) AS ?birthDate )
}
ORDER BY ASC(?birthDate)
LIMIT 1
